use std::{num::NonZeroU16,sync::Arc};
use typst_core::{compiler::{math::layout::MathLayouter,layout::FixedMetrics},entities::{content::{Content,SourceContent},file_id::FileId,span::Span,layout_types::{TextStyle,Pt,FrameItem}}};
fn src(body:Content,on:bool)->Content{if !on{return body}Content::Source(Arc::new(SourceContent{body,span:Span::from_range(FileId::from_raw(NonZeroU16::new(1).unwrap()),2..5)}))}
fn text(s:&str)->Content{Content::MathText(s.into())}
fn main(){let style=TextStyle::regular(Pt(12.0));let l=MathLayouter::new(&FixedMetrics,true,&style);for name in ["break","align"]{for on in [false,true]{let nodes=if name=="break"{vec![text("a"),src(Content::linebreak(),on),text("b")]}else{vec![text("1"),src(Content::math_align_point(),on),text("2"),Content::linebreak(),text("333"),src(Content::math_align_point(),on),text("4")]};let(items,e)=l.layout_equation_measured(&Content::MathSequence(nodes.into()),&style);let p:Vec<_>=items.iter().map(|i|match i{FrameItem::Text{pos,text,..}=>(text.to_string(),pos.x.val(),pos.y.val()),other=>panic!("Unknown {other:?}")}).collect();println!("{name} source={on} lines={} width={} first={} last={} positions={p:?}",e.line_count,e.width,e.first_baseline,e.last_baseline);}}}
